let img;
let particles = [];
let edgeColour;

function preload(){
	img = loadImage("https://openprocessing.org/sketch/1716661/files/face2.jpg");
}

function setup() {


	createCanvas(img.width, img.height);

	colorMode(HSB, 255);

	edgeColour = color(random(255), 255, 255, 10);


	for(let i = 0; i < width; i++){
		for(let j = 0; j < height; j++){
			stroke(random(255), 200, 200);
			point(i, j);
		}
	} 

	for(let i = 0; i < 2000; i++){
		particles[i] = new Particle(edgeColour);
	}
}



function draw() {
	for(let i = 0; i < particles.length; i++){


    if(particles[i].pos.y < 0 || particles[i].pos.y > height 
			                        || particles[i].pos.x < 0 
			                        || particles[i].pos.x > width)
		{

      particles[i] = new Particle(edgeColour);
    }

    particles[i].update();
    particles[i].show();
  }
}



// === Tab: tab2 ===
class Particle{

	constructor(colour, isRandom){

		colorMode(RGB, 255);





		this.pos = createVector(random(width), 0);
		this.vel = createVector(0, 1);




		this.c = color(0);
		this.edgeColour = colour;
	}

	update(){

		this.pos.add(this.vel);
		this.c = 0;

		if(brightness(  img.get(    int(this.pos.x), int(this.pos.y)    )  ) > 63){

     this.vel.rotate(random(-QUARTER_PI, QUARTER_PI));
     this.c = this.edgeColour;
   }
	}

	show(){


		stroke(this.c);
		point(this.pos.x, this.pos.y);
	}

}

